const VALUE_TOL: f64 = 1e-9;
const GRAD_TOL: f64 = 1e-8;
const FIT_TOL: f64 = 1e-6;
const FIT_CLUSTER: f64 = 1e-4;
const CHAOTIC_RANGE: f64 = 1e-3;
/// Values of different regimes of BoTorch's qLogNEI outcomes are at least
/// this far apart (log space).
const REGIME_GAP: f64 = 1e-7;
/// The seed of the samplers whose base samples are all recorded.
const UNRECORDED_SEED: u64 = 12345;

/// A number written by the fixture generator ("inf", "-inf" and "nan" as
/// strings).
#[derive(Clone, Copy, Debug)]
struct F(f64);

impl<'de> Deserialize<'de> for F {
    fn deserialize<D: serde::Deserializer<'de>>(d: D) -> Result<Self, D::Error> {
        let v = Value::deserialize(d)?;
        Ok(F(num(&v)))
    }
}

fn num(v: &Value) -> f64 {
    match v {
        Value::Number(n) => n.as_f64().unwrap(),
        Value::String(s) => match s.as_str() {
            "inf" => f64::INFINITY,
            "-inf" => f64::NEG_INFINITY,
            "nan" => f64::NAN,
            other => panic!("not a number: {other}"),
        },
        other => panic!("not a number: {other}"),
    }
}

fn flatten_value(v: &Value) -> Vec<f64> {
    match v {
        Value::Array(a) => a.iter().flat_map(flatten_value).collect(),
        other => vec![num(other)],
    }
}

fn mat(v: &Value) -> Matrix {
    let rows: Vec<Vec<f64>> = v.as_array().unwrap().iter().map(flatten_value).collect();
    matrix(&rows)
}

