fn load() -> Vec<Case> {
    let dir: PathBuf = fixture_dir().join("7a_multitask");
    let mut paths: Vec<PathBuf> = std::fs::read_dir(&dir)
        .unwrap_or_else(|e| panic!("cannot read {}: {e}", dir.display()))
        .map(|e| e.unwrap().path())
        .filter(|p| {
            p.file_name()
                .and_then(|n| n.to_str())
                .is_some_and(|n| n.starts_with("mtgp_") && n.ends_with(".json"))
        })
        .collect();
    paths.sort();
    assert!(!paths.is_empty(), "no fixtures in {}", dir.display());
    paths
        .iter()
        .map(|p| serde_json::from_str(&std::fs::read_to_string(p).unwrap()).unwrap())
        .collect()
}

// ----------------------------------------------------------------------
// The data kernel of a spec
// ----------------------------------------------------------------------

fn prior_of(v: &Value) -> Prior {
    let name = v[0].as_str().unwrap();
    let a: Vec<f64> = v[1].as_array().unwrap().iter().map(num).collect();
    match name {
        "GammaPrior" => Prior::gamma(a[0], a[1]),
        "LogNormalPrior" => Prior::log_normal(a[0], a[1]),
        "NormalPrior" => Prior::normal(a[0], a[1]),
        other => panic!("unknown prior {other}"),
    }
    .unwrap()
    .rounded_to_f32()
}

fn constraint_of(v: &Value) -> Constraint {
    let name = v[0].as_str().unwrap();
    let a: Vec<f64> = v[1].as_array().unwrap().iter().map(num).collect();
    match name {
        "GreaterThan" => GreaterThan::new(a[0], Some(ParameterTransform::Softplus), None)
            .rounded_to_f32()
            .into(),
        "Interval" => Interval::new(a[0], a[1], Some(ParameterTransform::Sigmoid), None, None)
            .unwrap()
            .rounded_to_f32()
            .into(),
        other => panic!("unknown constraint {other}"),
    }
}

fn node(spec: &Value) -> KernelNode {
    let ty = spec["type"].as_str().unwrap();
    let kw = &spec["kwargs"];
    let args: Vec<&Value> = spec["args"].as_array().unwrap().iter().collect();
    let ard = kw
        .get("ard_num_dims")
        .and_then(Value::as_u64)
        .map(|v| v as usize);
    let with_ls = |mut n: KernelNode| {
        if let Some(p) = kw.get("lengthscale_prior") {
            n = n
                .with_prior("raw_lengthscale", prior_of(&p["__prior__"]))
                .unwrap();
        }
        if let Some(c) = kw.get("lengthscale_constraint") {
            n = n
                .with_constraint("raw_lengthscale", constraint_of(&c["__constraint__"]))
                .unwrap();
        }
        n
    };
    let mut n = match ty {
        "RBFKernel" => with_ls(KernelNode::stationary(KernelKind::Rbf, ard).unwrap()),
        "MaternKernel" => {
            let nu = kw.get("nu").map_or(2.5, num);
            with_ls(KernelNode::stationary(KernelKind::matern(nu).unwrap(), ard).unwrap())
        }
        "PeriodicKernel" => with_ls(KernelNode::periodic(ard).unwrap()),
        "ScaleKernel" => KernelNode::scale(node(&args[0]["__kernel__"])),
        "AdditiveKernel" => {
            KernelNode::additive(args.iter().map(|a| node(&a["__kernel__"])).collect()).unwrap()
        }
        "ProductKernel" => {
            KernelNode::product(args.iter().map(|a| node(&a["__kernel__"])).collect()).unwrap()
        }
        other => panic!("unsupported kernel {other}"),
    };
    if let Some(dims) = kw.get("active_dims") {
        let dims: Vec<usize> = dims
            .as_array()
            .unwrap()
            .iter()
            .map(|v| v.as_u64().unwrap() as usize)
            .collect();
        n = n.with_active_dims(dims).unwrap();
    }
    n
}

// ----------------------------------------------------------------------
// Models
// ----------------------------------------------------------------------

fn usizes(v: &Value) -> Option<Vec<usize>> {
    v.as_array()
        .map(|a| a.iter().map(|x| x.as_u64().unwrap() as usize).collect())
}

fn i64s(v: &Value) -> Option<Vec<i64>> {
    v.as_array()
        .map(|a| a.iter().map(|x| x.as_i64().unwrap()).collect())
}

fn build(c: &Case, train_x: &Matrix) -> MultiTaskGP {
    let k = &c.case;
    let num_tasks = i64s(&k["all_tasks"]).map_or_else(
        || {
            let mut t = i64s(&k["tasks"]).unwrap();
            t.sort_unstable();
            t.dedup();
            t.len()
        },
        |a| a.len(),
    );
    let task_covar_prior = match k.get("prior").and_then(Value::as_str).unwrap_or("default") {
        "default" => TaskCovarPrior::Default,
        "none" => TaskCovarPrior::None,
        "gamma" => TaskCovarPrior::Prior(MatrixPrior::Elementwise(
            Prior::gamma(2.0, 2.0).unwrap().rounded_to_f32(),
        )),
        "lkj" => TaskCovarPrior::Prior(MatrixPrior::LkjCovariance {
            n: num_tasks,
            eta: 1.5,
            sd_prior: Prior::gamma(2.0, 1.5).unwrap().rounded_to_f32(),
        }),
        other => panic!("unknown prior {other}"),
    };
    let fixed = k.get("fixed_noise").and_then(Value::as_bool) == Some(true);
    let options = MultiTaskGPOptions {
        train_yvar: if fixed {
            Some(matrix(c.train_yvar.as_ref().unwrap()))
        } else {
            None
        },
        mean: if k.get("mean").and_then(Value::as_str) == Some("constant") {
            MultiTaskMean::Shared
        } else {
            MultiTaskMean::PerTask
        },
        covar_module: k.get("covar").filter(|v| !v.is_null()).map(node),
        likelihood: (k.get("likelihood").and_then(Value::as_str) == Some("gaussian"))
            .then(|| MultiTaskNoise::Shared(get_gaussian_likelihood_with_lognormal_prior())),
        task_covar_prior,
        output_tasks: k.get("output_tasks").and_then(i64s),
        rank: k.get("rank").and_then(Value::as_u64).map(|v| v as usize),
        all_tasks: k.get("all_tasks").and_then(i64s),
        outcome_transform: if k.get("standardize").and_then(Value::as_bool) == Some(false) {
            OutcomeTransformChoice::None
        } else {
            OutcomeTransformChoice::Default
        },
        input_transform: k
            .get("normalize")
            .and_then(usizes)
            .map(|idx| Normalize::new(idx.len())),
        input_transform_indices: k.get("normalize").and_then(usizes),
        validate_task_values: k.get("validate").and_then(Value::as_bool) != Some(false),
        ..Default::default()
    };
    MultiTaskGP::new(
        train_x.clone(),
        matrix(&c.train_y),
        k["task_feature"].as_i64().unwrap() as isize,
        options,
    )
    .unwrap()
}

fn grad_err(a: &[f64], e: &[f64]) -> f64 {
    let scale = e.iter().fold(0.0f64, |m, v| m.max(v.abs()));
    a.iter()
        .zip(e)
        .map(|(a, e)| (a - e).abs() / scale.max(1e-300))
        .fold(0.0, f64::max)
}

fn log_err(a: f64, e: f64) -> f64 {
    if a == e {
        0.0
    } else {
        (a - e).abs() / e.abs().max(1.0)
    }
}

/// `(min, lower quartile, median, upper quartile)` of a sample.
fn quantiles(v: &[f64]) -> (f64, f64, f64, f64) {
    let mut s = v.to_vec();
    s.sort_by(f64::total_cmp);
    let q = |p: f64| {
        let pos = p * (s.len() - 1) as f64;
        let (lo, hi) = (pos.floor() as usize, pos.ceil() as usize);
        s[lo] + (s[hi] - s[lo]) * (pos - lo as f64)
    };
    (s[0], q(0.25), q(0.5), q(0.75))
}

fn median(mut xs: Vec<f64>) -> f64 {
    xs.sort_by(f64::total_cmp);
    let n = xs.len();
    if n == 0 {
        0.0
    } else if n % 2 == 1 {
        xs[n / 2]
    } else {
        0.5 * (xs[n / 2 - 1] + xs[n / 2])
    }
}

fn quantile_90(mut xs: Vec<f64>) -> f64 {
    xs.sort_by(f64::total_cmp);
    match xs.len() {
        0 => 0.0,
        1 => xs[0],
        n => {
            let pos = 0.9 * (n - 1) as f64;
            let lo = pos.floor() as usize;
            let hi = (lo + 1).min(n - 1);
            xs[lo] + (pos - lo as f64) * (xs[hi] - xs[lo])
        }
    }
}

fn sampler(draws: &BTreeMap<String, Vec<Vec<f64>>>) -> Arc<SobolQMCNormalSampler> {
    let n = draws.values().next().map_or(1, |z| z.len());
    let s = SobolQMCNormalSampler::new(n, Some(UNRECORDED_SEED)).unwrap();
    for z in draws.values() {
        s.set_base_samples(matrix(z)).unwrap();
    }
    Arc::new(s)
}

/// Values and gradients of `acqf` at the candidate sets `xs`.
fn evaluate(acqf: &dyn AcquisitionFunction, xs: &[Vec<Vec<f64>>]) -> (Vec<f64>, Vec<Vec<f64>>) {
    let mut values = Vec::new();
    let mut grads = Vec::new();
    for x in xs {
        let (v, g) = acqf.forward_with_grad(&matrix(x)).unwrap();
        values.push(v);
        grads.push(common::matrix_rows(&g));
    }
    (values, grads)
}

/// Compares MC evaluations (log space) with the regime of BoTorch's outcomes
/// on the model and its twins that botorch_rs's value falls into (see the
/// LCEMGP parity test).
fn check_mc(
    report: &mut Report,
    name: &str,
    what: &str,
    acqf: &dyn AcquisitionFunction,
    e: &McEval,
) {
    let (values, grads) = evaluate(acqf, &e.x);
    let vals = |v: &[F]| -> Vec<f64> { v.iter().map(|f| f.0).collect() };
    let flat = |g: &[Vec<Vec<f64>>]| -> Vec<Vec<f64>> { g.iter().map(|s| s.concat()).collect() };
    let outcomes: Vec<(Vec<f64>, Vec<Vec<f64>>)> =
        std::iter::once((vals(&e.values), flat(&e.grads)))
            .chain(
                e.twin_values
                    .iter()
                    .zip(&e.twin_grads)
                    .map(|(v, g)| (vals(v), flat(g))),
            )
            .collect();
    let mut worst = (0.0f64, 0.0f64, 0.0f64);
    for (i, (v, g)) in values.iter().zip(&grads).enumerate() {
        let ov: Vec<f64> = outcomes.iter().map(|(o, _)| o[i]).collect();
        let og: Vec<&Vec<f64>> = outcomes.iter().map(|(_, o)| &o[i]).collect();
        let gap =
            REGIME_GAP.max(100.0 * median(ov[1..].iter().map(|&o| log_err(o, ov[0])).collect()));
        let nearest = (0..ov.len())
            .min_by(|&a, &b| log_err(*v, ov[a]).total_cmp(&log_err(*v, ov[b])))
            .unwrap();
        let regime: Vec<usize> = (0..ov.len())
            .filter(|&j| log_err(ov[j], ov[nearest]) <= gap)
            .collect();
        let others: Vec<usize> = regime.iter().copied().filter(|&j| j != nearest).collect();
        let floor_v = median(
            others
                .iter()
                .map(|&j| log_err(ov[j], ov[nearest]))
                .collect(),
        );
        let floor_g = quantile_90(
            others
                .iter()
                .map(|&j| grad_err(og[j], og[nearest]))
                .collect(),
        );
        let tol_v = VALUE_TOL.max(10.0 * floor_v);
        let tol_g = GRAD_TOL.max(10.0 * floor_g);
        let best = regime
            .iter()
            .map(|&j| {
                let ev = log_err(*v, ov[j]);
                let eg = grad_err(g, og[j]);
                ((ev / tol_v).max(eg / tol_g), ev, eg)
            })
            .min_by(|a, b| a.0.total_cmp(&b.0))
            .unwrap();
        if best.0 >= worst.0 {
            worst = best;
        }
    }
    let label = format!("{what} q={}", e.q);
    report.check(
        name,
        &format!("{label} values (nearest)"),
        worst.1,
        f64::INFINITY,
    );
    report.check(
        name,
        &format!("{label} gradients (nearest)"),
        worst.2,
        f64::INFINITY,
    );
    report.check(
        name,
        &format!("{label} values and gradients (scaled)"),
        worst.0,
        1.0,
    );
}

fn check_eval(
    report: &mut Report,
    name: &str,
    what: &str,
    acqf: &dyn AcquisitionFunction,
    xs: &[Vec<Vec<f64>>],
    values: &[F],
    grads: &[Vec<Vec<f64>>],
) {
    let (v, g) = evaluate(acqf, xs);
    let ev: Vec<f64> = values.iter().map(|f| f.0).collect();
    report.check_slices(name, &format!("{what} values"), &v, &ev, VALUE_TOL);
    let eg: Vec<f64> = grads.iter().flat_map(|s| s.concat()).collect();
    report.check(
        name,
        &format!("{what} gradients"),
        grad_err(&g.concat(), &eg),
        GRAD_TOL,
    );
}

/// The joint posterior at `x` over the output tasks (`d` columns) or with task
/// columns (`d + 1`), and the gradient of the weighted sum.
fn check_joint(report: &mut Report, name: &str, what: &str, gp: &Arc<MultiTaskGP>, j: &Joint) {
    let x = matrix(&j.x);
    let q = x.nrows();
    let model: Arc<dyn Model> = if x.ncols() == gp.dim() {
        Arc::clone(gp) as Arc<dyn Model>
    } else {
        Arc::new(botorch_core::models::multitask::MultiTaskTaskInputs::new(
            Arc::clone(gp),
        ))
    };
    let m = model.num_outputs();
    let p = model.posterior(&x, false).unwrap();
    let pn = model.posterior(&x, true).unwrap();
    // BoTorch's mean is q x m; ours output-major.
    let mean: Vec<f64> = (0..q * m).map(|i| p.mean[(i % m) * q + i / m]).collect();
    report.check_slices(
        name,
        &format!("{what} mean"),
        &mean,
        &common::flatten(&j.mean),
        VALUE_TOL,
    );
    report.check_slices(
        name,
        &format!("{what} covariance"),
        &common::matrix_rows(&p.covariance),
        &flatten_value(&j.covariance),
        VALUE_TOL,
    );
    report.check_slices(
        name,
        &format!("{what} covariance (noise)"),
        &common::matrix_rows(&pn.covariance),
        &flatten_value(&j.covariance_noisy),
        VALUE_TOL,
    );
    // Weighted sum: the mean weights are q x m (BoTorch's layout).
    let wm = Vector::from_fn(q * m, |a, _| j.weights_mean[a % q][a / q]);
    let wc = mat(&j.weights_cov);
    let g = model.joint_posterior_vjp(&x, 0..q, &wm, &wc).unwrap();
    report.check(
        name,
        &format!("{what} d (weighted sum) / dx"),
        grad_err(&common::matrix_rows(&g), &common::flatten(&j.dx)),
        GRAD_TOL,
    );
}

fn check_marginal(
    report: &mut Report,
    name: &str,
    what: &str,
    gp: &MultiTaskGP,
    f: &Marginal,
    xq: &Matrix,
    noise: bool,
) {
    let (b, d) = xq.shape();
    let m = Model::num_outputs(gp);
    let mut mean = Vec::new();
    let mut cov = Vec::new();
    let mut dm = Matrix::zeros(b, d);
    let mut dv = Matrix::zeros(b, d);
    for p in 0..b {
        let xp = xq.rows(p, 1).into_owned();
        let post = gp.posterior(&xp, noise).unwrap();
        mean.extend(post.mean.iter());
        cov.extend(common::matrix_rows(&post.covariance));
        if !noise {
            let ones = Vector::from_element(m, 1.0);
            let zeros = Matrix::zeros(m, m);
            let g = gp.joint_posterior_vjp(&xp, 0..1, &ones, &zeros).unwrap();
            dm.set_row(p, &g.row(0));
            // d (sum of the clamped variances) / dx.
            let gv = gp
                .joint_posterior_vjp(&xp, 0..1, &Vector::zeros(m), &Matrix::identity(m, m))
                .unwrap();
            dv.set_row(p, &gv.row(0));
        }
    }
    report.check_slices(
        name,
        &format!("{what} mean"),
        &mean,
        &common::flatten(&f.mean),
        VALUE_TOL,
    );
    report.check_slices(
        name,
        &format!("{what} output covariance"),
        &cov,
        &f.covariance
            .iter()
            .flat_map(|c| common::flatten(c))
            .collect::<Vec<_>>(),
        VALUE_TOL,
    );
    // Point posteriors (the analytic acquisition path) agree with them.
    if !noise {
        let pp = gp.point_posteriors(xq).unwrap();
        let ppm: Vec<f64> = common::matrix_rows(&pp.mean);
        report.check_slices(name, "point posteriors vs joint (mean)", &ppm, &mean, 1e-12);
        report.check(
            name,
            &format!("{what} d mean / dx"),
            grad_err(&common::matrix_rows(&dm), &common::flatten(&f.dmean_dx)),
            GRAD_TOL,
        );
        report.check(
            name,
            &format!("{what} d variance / dx"),
            grad_err(&common::matrix_rows(&dv), &common::flatten(&f.dvariance_dx)),
            GRAD_TOL,
        );
    }
}

#[test]
fn multitask_gp_matches_botorch() {
    let mut report = Report::default();
    for c in load() {
        let name = c.name.as_str();
        let x = matrix(&c.train_x);
        let mut gp = build(&c, &x);
        // Structure, bounds and default raw parameters.
        let shapes = gp.parameter_shapes();
        assert_eq!(shapes, c.param_names, "{name}: parameter names and shapes");
        let bounds: Vec<(f64, f64)> = c.bounds.iter().map(|(a, b)| (a.0, b.0)).collect();
        assert_eq!(gp.raw_parameter_bounds(), bounds, "{name}: bounds");
        let names = gp.parameter_names();
        let mut off = 0;
        let mut default_err = 0.0f64;
        for (n, size) in &names {
            if !n.contains("covar_factor") && !n.ends_with(".raw_var") {
                for i in off..off + size {
                    default_err =
                        default_err.max((gp.raw_parameters()[i] - c.default_raw[i]).abs());
                }
            }
            off += size;
        }
        report.check(
            name,
            "default raw parameters (non-random)",
            default_err,
            0.0,
        );
        gp.set_raw_parameters(&c.default_raw).unwrap();
        let (v, g) = gp.mll_value_and_grad(&c.default_raw).unwrap();
        report.check_slices(name, "default MLL", &[v], &[c.default_mll.value], VALUE_TOL);
        report.check(
            name,
            "default MLL gradient",
            grad_err(g.as_slice(), &c.default_mll.grad),
            GRAD_TOL,
        );
        let (v, g) = gp.mll_value_and_grad(&c.raw).unwrap();
        report.check_slices(name, "MLL", &[v], &[c.mll.value], VALUE_TOL);
        report.check(
            name,
            "MLL gradient",
            grad_err(g.as_slice(), &c.mll.grad),
            GRAD_TOL,
        );
        gp.set_raw_parameters(&c.raw).unwrap();
        gp.eval_unobserved_task_factors();
        report.check_slices(
            name,
            "raw parameters after eval()",
            gp.raw_parameters().as_slice(),
            &c.eval_raw,
            1e-15,
        );
        gp.set_raw_parameters(&c.eval_raw).unwrap();
        let gp = Arc::new(gp);

        // Posteriors.
        let xq = matrix(&c.marginal.x);
        check_marginal(
            &mut report,
            name,
            "point posterior",
            &gp,
            &c.marginal,
            &xq,
            false,
        );
        check_marginal(
            &mut report,
            name,
            "point posterior (noise)",
            &gp,
            &c.marginal_noisy,
            &xq,
            true,
        );
        check_joint(&mut report, name, "joint posterior", &gp, &c.joint);
        check_joint(
            &mut report,
            name,
            "joint posterior (task inputs)",
            &gp,
            &c.joint_tasks,
        );

        // Conditioning and fantasies.
        let cond = &c.conditioning;
        let noise: Option<Vec<f64>> = cond.noise.as_ref().map(|n| common::flatten(n));
        let cm = gp
            .condition_on_observations(&matrix(&cond.x), &matrix(&cond.y), noise.as_deref())
            .unwrap();
        let tx = matrix(&cond.test_x);
        let pc = cm.posterior(&tx, false).unwrap();
        let q = tx.nrows();
        let m = Model::num_outputs(&cm);
        let mean: Vec<f64> = (0..q * m).map(|i| pc.mean[(i % m) * q + i / m]).collect();
        report.check_slices(
            name,
            "conditioned posterior mean",
            &mean,
            &common::flatten(&cond.mean),
            VALUE_TOL,
        );
        report.check_slices(
            name,
            "conditioned posterior covariance",
            &common::matrix_rows(&pc.covariance),
            &flatten_value(&cond.covariance),
            VALUE_TOL,
        );
        if let Some(f) = &c.fantasy {
            let models = gp
                .fantasize_with_base_samples(&matrix(&f.x), &matrix(&f.base_samples))
                .unwrap();
            let tx = matrix(&f.test_x);
            let fm = flatten_value(&f.mean);
            let fc = flatten_value(&f.covariance);
            let mut mean = Vec::new();
            let mut cov = Vec::new();
            for fmod in &models {
                let p = fmod.posterior(&tx, false).unwrap();
                mean.extend((0..q * m).map(|i| p.mean[(i % m) * q + i / m]));
                cov.extend(common::matrix_rows(&p.covariance));
            }
            report.check_slices(name, "fantasy posterior mean", &mean, &fm, VALUE_TOL);
            report.check_slices(name, "fantasy posterior covariance", &cov, &fc, VALUE_TOL);
        }

        // Fits from the default parameters.
        if let Some(f) = &c.fit {
            let mut fitted = build(&c, &x);
            fitted.set_raw_parameters(&c.default_raw).unwrap();
            let r = fit_gpytorch_mll(&mut fitted, FitOptions::default()).unwrap();
            let bt: Vec<f64> = std::iter::once((f.loss, f.attempts))
                .chain(
                    f.twin_losses
                        .iter()
                        .copied()
                        .zip(f.twin_attempts.iter().copied()),
                )
                .filter(|&(_, a)| a == 1)
                .map(|(l, _)| l)
                .collect();
            let rs: Vec<f64> = std::iter::once((r.loss, r.attempts))
                .chain(f.twin_train_x.iter().map(|tx| {
                    let mut twin = build(&c, &matrix(tx));
                    twin.set_raw_parameters(&c.default_raw).unwrap();
                    let t = fit_gpytorch_mll(&mut twin, FitOptions::default()).unwrap();
                    (t.loss, t.attempts)
                }))
                .filter(|&(_, a)| a == 1)
                .map(|(l, _)| l)
                .collect();
            let bt_best = bt.iter().copied().fold(f64::INFINITY, f64::min);
            let bt_worst = bt.iter().copied().fold(f64::NEG_INFINITY, f64::max);
            let rs_best = rs.iter().copied().fold(f64::INFINITY, f64::min);
            let spread = bt
                .iter()
                .copied()
                .filter(|&l| l <= bt_best + FIT_CLUSTER)
                .fold(bt_best, f64::max)
                - bt_best;
            let tol = FIT_TOL.max(10.0 * spread);
            if bt_worst - bt_best > CHAOTIC_RANGE {
                let (bt_q, rs_q) = (quantiles(&bt), quantiles(&rs));
                report.check(
                    name,
                    "fit (chaotic): best above BoTorch's median",
                    (rs_q.0 - bt_q.2).max(0.0),
                    FIT_TOL,
                );
                report.check(
                    name,
                    "fit (chaotic): median above BoTorch's upper quartile",
                    (rs_q.2 - bt_q.3).max(0.0),
                    FIT_TOL,
                );
            } else {
                report.check(
                    name,
                    "fit: best loss above BoTorch's best (scaled)",
                    (rs_best - bt_best).max(0.0) / tol,
                    1.0,
                );
                if r.attempts == 1 {
                    report.check(
                        name,
                        "fit: loss above BoTorch's worst (scaled)",
                        (r.loss - bt_worst).max(0.0) / tol,
                        1.0,
                    );
                }
            }
            let diff = fitted
                .raw_parameters()
                .iter()
                .zip(&f.raw_params)
                .map(|(a, b)| (a - b).abs())
                .fold(0.0, f64::max);
            println!(
                "{name:26} fit: loss {:+.10} (BoTorch {:+.10}), iterations {} (BoTorch {}), \
                 max parameter difference {diff:.1e}, first-attempt outcomes: BoTorch \
                 [{bt_best:+.10}, {bt_worst:+.10}] ({} of 17), botorch_rs best {rs_best:+.10} \
                 ({} of 17), spread {spread:.1e}",
                r.loss,
                f.loss,
                r.iterations,
                f.iterations,
                bt.len(),
                rs.len()
            );
        }

        // Acquisition functions.
        if let Some(a) = &c.acquisition {
            let model: Arc<dyn Model> = Arc::clone(&gp) as Arc<dyn Model>;
            let xb = matrix(&a.x_baseline);
            for e in &a.qlognei {
                let acqf = QLogNoisyExpectedImprovement::new(
                    Arc::clone(&model),
                    &xb,
                    QLogNoisyExpectedImprovementOptions {
                        sampler: Some(sampler(&e.draws)),
                        prune_baseline: false,
                        ..Default::default()
                    },
                )
                .unwrap();
                check_mc(&mut report, name, "qLogNEI", &acqf, e);
            }
            // The model over all tasks with a scalarizing transform.
            let mut tasks: Vec<i64> = i64s(&c.case["tasks"]).unwrap();
            tasks.sort_unstable();
            tasks.dedup();
            let all: Arc<dyn Model> = Arc::new(gp.with_output_tasks(&tasks).unwrap());
            let s = &a.qucb_scalarized;
            let t =
                ScalarizedPosteriorTransform::new(Vector::from_vec(s.weights.clone()), s.offset)
                    .unwrap();
            let scal = ScalarizedModel::wrap(Arc::clone(&all), Some(t.clone())).unwrap();
            let ucb = QUpperConfidenceBound::new(
                Arc::clone(&scal),
                0.3,
                McAcquisitionOptions {
                    sampler: Some(sampler(&s.draws)),
                    ..Default::default()
                },
            )
            .unwrap();
            check_eval(
                &mut report,
                name,
                "qUCB (scalarized)",
                &ucb,
                &s.x,
                &s.values,
                &s.grads,
            );
            let l = &a.logei;
            let logei =
                LogExpectedImprovement::new(Arc::clone(&model), l.best_f.unwrap(), true).unwrap();
            check_eval(
                &mut report,
                name,
                "LogEI",
                &logei,
                &l.x,
                &l.values,
                &l.grads,
            );
            let pm = PosteriorMean::new(scal, true).unwrap();
            let p = &a.posterior_mean_scalarized;
            check_eval(
                &mut report,
                name,
                "PosteriorMean (scalarized)",
                &pm,
                &p.x,
                &p.values,
                &p.grads,
            );
        }
    }
    report.finish("7a multi-task GPs: MultiTaskGP vs BoTorch");
}

// ----------------------------------------------------------------------
// KroneckerMultiTaskGP
// ----------------------------------------------------------------------

#[derive(Deserialize)]
struct KronPosterior {
    x: Vec<Vec<f64>>,
    botorch_mean: Vec<Vec<f64>>,
    base_sample_shape: Vec<usize>,
    matheron_mean: Vec<Vec<f64>>,
    matheron_covariance: Vec<Vec<f64>>,
    matheron_covariance_noisy: Vec<Vec<f64>>,
    exact_mean: Vec<Vec<f64>>,
    exact_covariance: Vec<Vec<f64>>,
    exact_covariance_noisy: Vec<Vec<f64>>,
    weights_mean: Vec<Vec<f64>>,
    weights_cov: Vec<Vec<f64>>,
    dx: Vec<Vec<f64>>,
}

#[derive(Deserialize)]
struct KronQei {
    weights: Vec<f64>,
    best_f: f64,
    x: Vec<Vec<Vec<f64>>>,
    draws: BTreeMap<String, Vec<Vec<f64>>>,
    values: Vec<F>,
    grads: Vec<Vec<Vec<f64>>>,
}

#[derive(Deserialize)]
struct KronCase {
    name: String,
    case: Value,
    train_x: Vec<Vec<f64>>,
    train_y: Vec<Vec<f64>>,
    param_names: Vec<(String, Vec<usize>)>,
    bounds: Vec<(F, F)>,
    default_raw: Vec<f64>,
    default_mll: Mll,
    raw: Vec<f64>,
    mll: Mll,
    posterior: KronPosterior,
    fit: Option<Fit>,
    qei: Option<KronQei>,
}

fn load_kron() -> Vec<KronCase> {
    let dir: PathBuf = fixture_dir().join("7a_multitask");
    let mut paths: Vec<PathBuf> = std::fs::read_dir(&dir)
        .unwrap()
        .map(|e| e.unwrap().path())
        .filter(|p| {
            p.file_name()
                .and_then(|n| n.to_str())
                .is_some_and(|n| n.starts_with("kron_") && n.ends_with(".json"))
        })
        .collect();
    paths.sort();
    assert!(
        !paths.is_empty(),
        "no Kronecker fixtures in {}",
        dir.display()
    );
    paths
        .iter()
        .map(|p| serde_json::from_str(&std::fs::read_to_string(p).unwrap()).unwrap())
        .collect()
}

fn build_kron(c: &KronCase, train_x: &Matrix) -> KroneckerMultiTaskGP {
    let k = &c.case;
    let m = k["m"].as_u64().unwrap() as usize;
    let d = k["d"].as_u64().unwrap() as usize;
    let sd_prior = k.get("sd_box").and_then(Value::as_array).map(|a| {
        Prior::smoothed_box(num(&a[0]), num(&a[1]), num(&a[2]))
            .unwrap()
            .rounded_to_f32()
    });
    let options = KroneckerMultiTaskGPOptions {
        data_covar_module: k.get("covar").filter(|v| !v.is_null()).map(node),
        eta: k.get("eta").map_or(1.5, |v| num(v) as f32 as f64),
        sd_prior,
        rank: k.get("rank").and_then(Value::as_u64).map(|v| v as usize),
        likelihood_rank: k
            .get("likelihood_rank")
            .and_then(Value::as_u64)
            .map_or(0, |v| v as usize),
        outcome_transform: (k.get("standardize").and_then(Value::as_bool) == Some(true))
            .then(Standardize::new),
        input_transform: (k.get("normalize").and_then(Value::as_bool) == Some(true))
            .then(|| Normalize::new(d)),
        ..Default::default()
    };
    let _ = m;
    KroneckerMultiTaskGP::new(train_x.clone(), matrix(&c.train_y), options).unwrap()
}

/// Interleaved (`p·m + t`) values of an output-major (`t·q + p`) vector.
fn interleave(v: &Vector, q: usize, m: usize) -> Vec<f64> {
    (0..q * m).map(|i| v[(i % m) * q + i / m]).collect()
}

/// The interleaved covariance of an output-major one.
fn interleave_cov(c: &Matrix, q: usize, m: usize) -> Vec<f64> {
    let idx = |i: usize| (i % m) * q + i / m;
    let mut out = Vec::with_capacity(q * m * q * m);
    for i in 0..q * m {
        for j in 0..q * m {
            out.push(c[(idx(i), idx(j))]);
        }
    }
    out
}

#[test]
fn kronecker_multitask_gp_matches_botorch() {
    let mut report = Report::default();
    for c in load_kron() {
        let name = c.name.as_str();
        let x = matrix(&c.train_x);
        let mut gp = build_kron(&c, &x);
        assert_eq!(
            gp.parameter_shapes(),
            c.param_names,
            "{name}: names and shapes"
        );
        let bounds: Vec<(f64, f64)> = c.bounds.iter().map(|(a, b)| (a.0, b.0)).collect();
        assert_eq!(gp.raw_parameter_bounds(), bounds, "{name}: bounds");
        // Default raw parameters, except the random factors.
        let mut off = 0;
        let mut err = 0.0f64;
        for (n, size) in gp.parameter_names() {
            if !n.ends_with("covar_factor") && !n.ends_with(".raw_var") {
                for i in off..off + size {
                    err = err.max((gp.raw_parameters()[i] - c.default_raw[i]).abs());
                }
            }
            off += size;
        }
        report.check(
            name,
            "Kronecker: default raw parameters (non-random)",
            err,
            0.0,
        );
        let (v, g) = gp.mll_value_and_grad(&c.default_raw).unwrap();
        report.check_slices(
            name,
            "Kronecker: default MLL",
            &[v],
            &[c.default_mll.value],
            VALUE_TOL,
        );
        report.check(
            name,
            "Kronecker: default MLL gradient",
            grad_err(g.as_slice(), &c.default_mll.grad),
            GRAD_TOL,
        );
        let (v, g) = gp.mll_value_and_grad(&c.raw).unwrap();
        report.check_slices(name, "Kronecker: MLL", &[v], &[c.mll.value], VALUE_TOL);
        report.check(
            name,
            "Kronecker: MLL gradient",
            grad_err(g.as_slice(), &c.mll.grad),
            GRAD_TOL,
        );
        gp.set_raw_parameters(&c.raw).unwrap();

        // Posteriors: BoTorch's mean, the exact joint posterior (which is
        // the distribution of BoTorch's Matheron samples).
        let pf = &c.posterior;
        let xq = matrix(&pf.x);
        let (q, m) = (xq.nrows(), gp.num_tasks());
        let p = gp.posterior(&xq, false).unwrap();
        let pn = gp.posterior(&xq, true).unwrap();
        let mean = interleave(&p.mean, q, m);
        report.check_slices(
            name,
            "Kronecker: posterior mean (BoTorch)",
            &mean,
            &common::flatten(&pf.botorch_mean),
            VALUE_TOL,
        );
        report.check_slices(
            name,
            "Kronecker: posterior mean (Matheron)",
            &mean,
            &common::flatten(&pf.matheron_mean),
            VALUE_TOL,
        );
        report.check_slices(
            name,
            "Kronecker: posterior mean (exact)",
            &mean,
            &common::flatten(&pf.exact_mean),
            VALUE_TOL,
        );
        let cov = interleave_cov(&p.covariance, q, m);
        report.check_slices(
            name,
            "Kronecker: covariance (BoTorch's Matheron samples)",
            &cov,
            &common::flatten(&pf.matheron_covariance),
            VALUE_TOL,
        );
        report.check_slices(
            name,
            "Kronecker: covariance (exact)",
            &cov,
            &common::flatten(&pf.exact_covariance),
            VALUE_TOL,
        );
        let covn = interleave_cov(&pn.covariance, q, m);
        report.check_slices(
            name,
            "Kronecker: covariance (noise, Matheron)",
            &covn,
            &common::flatten(&pf.matheron_covariance_noisy),
            VALUE_TOL,
        );
        report.check_slices(
            name,
            "Kronecker: covariance (noise, exact)",
            &covn,
            &common::flatten(&pf.exact_covariance_noisy),
            VALUE_TOL,
        );
        // The base sample shape and our Matheron samples' distribution.
        let n = gp.num_train();
        assert_eq!(
            pf.base_sample_shape,
            vec![(n + q) * m + n * m],
            "{name}: base sample shape"
        );
        let total = pf.base_sample_shape[0];
        let mut z = Matrix::zeros(total + 1, total);
        for i in 0..total {
            z[(i + 1, i)] = 1.0;
        }
        let s = gp.matheron_samples(&xq, &z, false).unwrap();
        let a = Matrix::from_fn(total, q * m, |i, j| s[(i + 1, j)] - s[(0, j)]);
        let mc = a.transpose() * &a;
        report.check_slices(
            name,
            "Kronecker: own Matheron samples covariance",
            &common::matrix_rows(&mc),
            &common::flatten(&pf.exact_covariance),
            VALUE_TOL,
        );
        // The input gradient of a weighted sum of the exact mean and
        // covariance (weights in BoTorch's interleaved layout).
        let wm = Vector::from_fn(q * m, |a, _| pf.weights_mean[a % q][a / q]);
        let wci = matrix(&pf.weights_cov);
        let idx = |i: usize| (i % q) * m + i / q;
        let wc = Matrix::from_fn(q * m, q * m, |a, b| wci[(idx(a), idx(b))]);
        let gx = gp.joint_posterior_vjp(&xq, 0..q, &wm, &wc).unwrap();
        report.check(
            name,
            "Kronecker: d (weighted sum) / dx",
            grad_err(&common::matrix_rows(&gx), &common::flatten(&pf.dx)),
            GRAD_TOL,
        );

        if let Some(e) = &c.qei {
            let model: Arc<dyn Model> = Arc::new(gp.clone());
            let obj: Arc<dyn McObjective> =
                Arc::new(LinearMcObjective::new(Vector::from_vec(e.weights.clone())).unwrap());
            let acqf = QExpectedImprovement::new(
                model,
                e.best_f,
                McAcquisitionOptions {
                    sampler: Some(sampler(&e.draws)),
                    objective: Some(obj),
                    ..Default::default()
                },
            )
            .unwrap();
            check_eval(
                &mut report,
                name,
                "Kronecker: qEI (linear objective)",
                &acqf,
                &e.x,
                &e.values,
                &e.grads,
            );
        }

        if let Some(f) = &c.fit {
            let mut fitted = build_kron(&c, &x);
            fitted.set_raw_parameters(&c.default_raw).unwrap();
            let r = fit_gpytorch_mll(&mut fitted, FitOptions::default()).unwrap();
            let bt: Vec<f64> = std::iter::once((f.loss, f.attempts))
                .chain(
                    f.twin_losses
                        .iter()
                        .copied()
                        .zip(f.twin_attempts.iter().copied()),
                )
                .filter(|&(_, a)| a == 1)
                .map(|(l, _)| l)
                .collect();
            let rs: Vec<f64> = std::iter::once((r.loss, r.attempts))
                .chain(f.twin_train_x.iter().map(|tx| {
                    let mut twin = build_kron(&c, &matrix(tx));
                    twin.set_raw_parameters(&c.default_raw).unwrap();
                    let t = fit_gpytorch_mll(&mut twin, FitOptions::default()).unwrap();
                    (t.loss, t.attempts)
                }))
                .filter(|&(_, a)| a == 1)
                .map(|(l, _)| l)
                .collect();
            let bt_best = bt.iter().copied().fold(f64::INFINITY, f64::min);
            let bt_worst = bt.iter().copied().fold(f64::NEG_INFINITY, f64::max);
            let rs_best = rs.iter().copied().fold(f64::INFINITY, f64::min);
            let spread = bt
                .iter()
                .copied()
                .filter(|&l| l <= bt_best + FIT_CLUSTER)
                .fold(bt_best, f64::max)
                - bt_best;
            let tol = FIT_TOL.max(10.0 * spread);
            if bt_worst - bt_best > CHAOTIC_RANGE {
                let (bt_q, rs_q) = (quantiles(&bt), quantiles(&rs));
                report.check(
                    name,
                    "Kronecker fit (chaotic): best above BoTorch's median",
                    (rs_q.0 - bt_q.2).max(0.0),
                    FIT_TOL,
                );
                report.check(
                    name,
                    "Kronecker fit (chaotic): median above BoTorch's upper quartile",
                    (rs_q.2 - bt_q.3).max(0.0),
                    FIT_TOL,
                );
            } else {
                report.check(
                    name,
                    "Kronecker fit: best loss above BoTorch's best (scaled)",
                    (rs_best - bt_best).max(0.0) / tol,
                    1.0,
                );
                if r.attempts == 1 {
                    report.check(
                        name,
                        "Kronecker fit: loss above BoTorch's worst (scaled)",
                        (r.loss - bt_worst).max(0.0) / tol,
                        1.0,
                    );
                }
            }
            println!(
                "{name:26} Kronecker fit: loss {:+.10} (BoTorch {:+.10}), iterations {} (BoTorch {}), \
                 first-attempt outcomes: BoTorch [{bt_best:+.10}, {bt_worst:+.10}] ({} of 17), \
                 botorch_rs best {rs_best:+.10} ({} of 17), spread {spread:.1e}",
                r.loss,
                f.loss,
                r.iterations,
                f.iterations,
                bt.len(),
                rs.len()
            );
        }
    }
    report.finish("7a multi-task GPs: KroneckerMultiTaskGP vs BoTorch");
}
